 using System.ComponentModel;
 using System.Text.Json;
 using ModelContextProtocol.Server;

 [McpServerToolType]
 public class WeatherTools
 {
     private readonly IHttpClientFactory _httpClientFactory;

     public WeatherTools(IHttpClientFactory httpClientFactory)
     {
         _httpClientFactory = httpClientFactory;
     }

     [McpServerTool(Name = "get_weather"),
      Description("Get current weather for a location by latitude and longitude.")]
     public async Task<string> GetWeather(
         [Description("Latitude of the location")] double latitude,
         [Description("Longitude of the location")] double longitude)
     {
         using var client = _httpClientFactory.CreateClient("WeatherApi");

         var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";
         var response = await client.GetAsync(url);
         response.EnsureSuccessStatusCode();

         var json = await response.Content.ReadAsStringAsync();
         using var doc = JsonDocument.Parse(json);
         var weather = doc.RootElement.GetProperty("current_weather");

         return $"Temperature: {weather.GetProperty("temperature")}°C, " +
                $"Wind: {weather.GetProperty("windspeed")} km/h, " +
                $"Condition code: {weather.GetProperty("weathercode")}";
     }

     [McpServerTool(Name = "get_location_weather"),
      Description("Get weather summary for a named location using geocoding.")]
     public async Task<string> GetLocationWeather(
         [Description("City or place name to look up")] string location)
     {
         using var client = _httpClientFactory.CreateClient("WeatherApi");

         var geoUrl = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(location)}&count=1";
         var geoResponse = await client.GetAsync(geoUrl);
         geoResponse.EnsureSuccessStatusCode();

         var geoJson = await geoResponse.Content.ReadAsStringAsync();
         using var geoDoc = JsonDocument.Parse(geoJson);

         if (!geoDoc.RootElement.TryGetProperty("results", out var results) ||
             results.GetArrayLength() == 0)
         {
             return $"Location '{location}' not found.";
         }

         var place = results[0];
         var lat = place.GetProperty("latitude").GetDouble();
         var lon = place.GetProperty("longitude").GetDouble();
         var name = place.GetProperty("name").GetString();

         return $"Weather for {name}: {await GetWeather(lat, lon)}";
     }
 }

